"""Route-B algorithm ablations and sensitivity experiments."""
from __future__ import annotations
import argparse,csv,json,os
from config import Weights
from data import prepare_instance
from solve_direct_gurobi import INSTANCES,solve_direct_gurobi
from solver_true_benders import solve_true_benders_pipeline
FIELDS="instance seed algorithm status runtime nodes ub lb gap root_initial_bound root_final_bound root_bound_improvement initial_opt_cuts root_opt_cuts incumbent_opt_cuts node_opt_cuts incumbent_feas_cuts node_feas_cuts unique_cuts inherited_cuts sp_solves sp_total_time callback_time alns_start_ub alns_best_ub alns_improvement epsilon attribute_score core_degradation handling_rate_scale alloc_domain".split()
def configs(full=False):
    base=[{"algorithm":"direct_gurobi","direct":True},{"algorithm":"bbc_without_root","root":False},{"algorithm":"bbc_with_root"},{"algorithm":"bbc_without_node_cuts","node":False},{"algorithm":"bbc_without_valid_inequalities","valid":False},{"algorithm":"bbc_without_warm_start","warm":False},{"algorithm":"bbc_only","alns":False,"phase3":False,"refine":False},{"algorithm":"bbc_alns","phase3":False,"refine":False},{"algorithm":"bbc_alns_phase3_inheritance","refine":False},{"algorithm":"full_with_refinement"}]
    if full:base += [{"algorithm":f"handling_{x}","rate":x} for x in (.5,1.5)]+[{"algorithm":f"epsilon_{x}","epsilon":x} for x in (0,.005,.02,.05)]+[{"algorithm":"alloc_continuous","domain":"continuous"}]+[{"algorithm":f"node_limit_{x}","node_limit":x} for x in (0,20,200)]+[{"algorithm":f"root_iters_{x}","root_iters":x} for x in (5,50)]
    return base
def run_one(instance,seed,cfg,t):
    rate=cfg.get("rate",1);domain=cfg.get("domain","integer");d=prepare_instance(INSTANCES[instance](),rate)
    if cfg.get("direct"):
        q=solve_direct_gurobi(d,Weights(),time_limit=3*t,mip_gap=.03,alloc_domain=domain,seed=seed);return {"instance":instance,"seed":seed,"algorithm":cfg["algorithm"],"status":q["status_name"],"runtime":q["runtime"],"nodes":q["nodes"],"ub":q["ub"],"lb":q["lb"],"gap":q["gap"],"handling_rate_scale":rate,"alloc_domain":domain}
    r=solve_true_benders_pipeline(d,Weights(),phase1_time=t,lns_time=t,phase3_time=t,attribute_time=t,alloc_domain=domain,root_prepass=cfg.get("root",True),root_cut_max_iters=cfg.get("root_iters",20),root_cut_time=t,node_cuts=cfg.get("node",True),node_cut_limit=cfg.get("node_limit",100),add_valid_inequalities=cfg.get("valid",True),warm_start=cfg.get("warm",True),enable_alns=cfg.get("alns",True),enable_phase3=cfg.get("phase3",True),enable_refinement=cfg.get("refine",True),attribute_epsilon=cfg.get("epsilon",.01),seed=seed);p0=r.get("phase0_root_prepass",{});p1=r.get("phase1_bbc",{});p3=r.get("phase3_bbc",{});cs=p1.get("cut_statistics",{});sp=p1.get("sp_statistics",{});a=r.get("phase2_alns",{});ref=r.get("attribute_refinement",{});core=r.get("core_best",{});row={"instance":instance,"seed":seed,"algorithm":cfg["algorithm"],"status":p1.get("status_name","FAILED"),"runtime":sum(float(x.get("runtime",0) or 0) for x in (p1,a,p3))+float(p0.get("root_cut_runtime",0) or 0),"nodes":float(p1.get("nodes",0) or 0)+float(p3.get("nodes",0) or 0),"ub":core.get("ub"),"lb":core.get("lb"),"gap":core.get("gap"),"root_initial_bound":p0.get("root_initial_bound"),"root_final_bound":p0.get("root_final_bound"),"root_bound_improvement":p0.get("root_bound_improvement"),"initial_opt_cuts":cs.get("initial_optimality_cuts"),"root_opt_cuts":p0.get("root_cut_count"),"incumbent_opt_cuts":cs.get("incumbent_optimality_cuts"),"node_opt_cuts":cs.get("node_optimality_cuts"),"incumbent_feas_cuts":cs.get("incumbent_feasibility_cuts"),"node_feas_cuts":cs.get("node_feasibility_cuts"),"unique_cuts":r.get("total_unique_cuts"),"inherited_cuts":r.get("cuts_inherited_by_phase3"),"sp_solves":sp.get("sp_solve_count"),"sp_total_time":sp.get("sp_total_time"),"callback_time":cs.get("callback_time"),"alns_start_ub":a.get("start_ub"),"alns_best_ub":a.get("best_ub"),"alns_improvement":a.get("improvement"),"epsilon":ref.get("epsilon"),"attribute_score":ref.get("attribute_after"),"core_degradation":ref.get("core_degradation"),"handling_rate_scale":rate,"alloc_domain":domain};return row
def main():
    p=argparse.ArgumentParser();p.add_argument("--instances",nargs="+",choices=INSTANCES,default=["tiny"]);p.add_argument("--seeds",nargs="+",type=int,default=[0]);p.add_argument("--time",type=float,default=3);p.add_argument("--suite",choices=("quick","full"),default="quick");p.add_argument("--output",default="experiments");a=p.parse_args();os.makedirs(a.output,exist_ok=True);rows=[run_one(i,s,c,a.time) for i in a.instances for s in a.seeds for c in configs(a.suite=="full")];f=open(os.path.join(a.output,"results.csv"),"w",newline="",encoding="utf8");w=csv.DictWriter(f,fieldnames=FIELDS,extrasaction="ignore");w.writeheader();w.writerows(rows);f.close();json.dump(rows,open(os.path.join(a.output,"results.json"),"w",encoding="utf8"),indent=2);print(f"wrote {len(rows)} rows")
if __name__=="__main__":main()
